def match(u):
    if u == '/':
        return 'Home'
    parts = u.strip('/').split('/')
    if parts == ['posts']:
        return 'PostList'
    if len(parts) == 2 and parts[0] == 'posts' and parts[1] != '':
        return 'PostDetail'
    return 'NotFound'

urls = ['/', '/posts', '/posts/42', '/posts/42/comments', '/blog', '/posts/abc']
res = [match(u) for u in urls]
print(res.count('PostDetail'))
print(res.count('NotFound'))
